-- Expand each N4 grammar point from one example to five.
-- Existing seeded examples are retained; four additional contextual examples are appended.
begin;
do $expand_n4_grammar_examples$
declare
  v_examples jsonb := $n4_examples$[{"jlpt_level":"N4","sort_order":1,"additional_examples":[{"japanese":"日本では家に入る前に靴を脱がなければなりません。","romaji":"Nihon de wa ie ni hairu mae ni kutsu o nuganakereba narimasen.","meaning":"In Japan, you must take off your shoes before entering a house."},{"japanese":"明日までにレポートを出さなければなりません。","romaji":"Ashita made ni repooto o dasanakereba narimasen.","meaning":"I have to submit the report by tomorrow."},{"japanese":"毎朝、薬を飲まなければなりません。","romaji":"Maiasa, kusuri o nomanakereba narimasen.","meaning":"I have to take medicine every morning."},{"japanese":"試験に合格するために、もっと勉強しなければなりません。","romaji":"Shiken ni goukaku suru tame ni, motto benkyou shinakereba narimasen.","meaning":"I must study more to pass the exam."}]},{"jlpt_level":"N4","sort_order":2,"additional_examples":[{"japanese":"今日は早く帰らなくてはいけません。","romaji":"Kyou wa hayaku kaeranaku te wa ikemasen.","meaning":"I have to go home early today."},{"japanese":"図書館では静かにしなくてはいけません。","romaji":"Toshokan de wa shizuka ni shinakute wa ikemasen.","meaning":"You have to be quiet in the library."},{"japanese":"出かける前に窓を閉めなくてはいけません。","romaji":"Dekakeru mae ni mado o shimenakute wa ikemasen.","meaning":"I have to close the window before going out."},{"japanese":"この書類に名前を書かなくてはいけません。","romaji":"Kono shorui ni namae o kakanakute wa ikemasen.","meaning":"You have to write your name on this form."}]},{"jlpt_level":"N4","sort_order":3,"additional_examples":[{"japanese":"明日は早く起きないといけません。","romaji":"Ashita wa hayaku okinai to ikemasen.","meaning":"I have to get up early tomorrow."},{"japanese":"もう帰らないといけません。","romaji":"Mou kaeranai to ikemasen.","meaning":"I have to go home now."},{"japanese":"駅で切符を買わないといけません。","romaji":"Eki de kippu o kawanai to ikemasen.","meaning":"I have to buy a ticket at the station."},{"japanese":"会議の前に資料を準備しないといけません。","romaji":"Kaigi no mae ni shiryou o junbi shinai to ikemasen.","meaning":"I have to prepare the materials before the meeting."}]},{"jlpt_level":"N4","sort_order":4,"additional_examples":[{"japanese":"今日は宿題をしなくてもいいです。","romaji":"Kyou wa shukudai o shinakute mo ii desu.","meaning":"You do not have to do homework today."},{"japanese":"ここでは靴を脱がなくてもいいです。","romaji":"Koko de wa kutsu o nuganakute mo ii desu.","meaning":"You do not have to take off your shoes here."},{"japanese":"全部食べなくてもいいですよ。","romaji":"Zenbu tabenakute mo ii desu yo.","meaning":"You do not have to eat everything."},{"japanese":"明日は学校へ来なくてもいいです。","romaji":"Ashita wa gakkou e konakute mo ii desu.","meaning":"You do not have to come to school tomorrow."}]},{"jlpt_level":"N4","sort_order":5,"additional_examples":[{"japanese":"ここに座ってもかまいません。","romaji":"Koko ni suwatte mo kamaimasen.","meaning":"You may sit here."},{"japanese":"少し遅れてもかまいませんか。","romaji":"Sukoshi okurete mo kamaimasen ka.","meaning":"Would it be all right if I am a little late?"},{"japanese":"この辞書を使ってもかまいません。","romaji":"Kono jisho o tsukatte mo kamaimasen.","meaning":"You may use this dictionary."},{"japanese":"窓を開けてもかまいませんか。","romaji":"Mado o akete mo kamaimasen ka.","meaning":"Would it be all right if I open the window?"}]},{"jlpt_level":"N4","sort_order":6,"additional_examples":[{"japanese":"この部屋でたばこを吸ってはなりません。","romaji":"Kono heya de tabako o sutte wa narimasen.","meaning":"You must not smoke in this room."},{"japanese":"試験中に隣の人と話してはなりません。","romaji":"Shiken chuu ni tonari no hito to hanashite wa narimasen.","meaning":"You must not talk to the person next to you during the exam."},{"japanese":"大切な書類を捨ててはなりません。","romaji":"Taisetsu na shorui o sutete wa narimasen.","meaning":"You must not throw away important documents."},{"japanese":"この川で泳いではなりません。","romaji":"Kono kawa de oyoide wa narimasen.","meaning":"You must not swim in this river."}]},{"jlpt_level":"N4","sort_order":7,"additional_examples":[{"japanese":"ここで写真を撮ってはいけません。","romaji":"Koko de shashin o totte wa ikemasen.","meaning":"You must not take photos here."},{"japanese":"授業中に携帯電話を使ってはいけません。","romaji":"Jugyou chuu ni keitai denwa o tsukatte wa ikemasen.","meaning":"You must not use a mobile phone during class."},{"japanese":"この薬をたくさん飲んではいけません。","romaji":"Kono kusuri o takusan nonde wa ikemasen.","meaning":"You must not take a lot of this medicine."},{"japanese":"人の部屋に勝手に入ってはいけません。","romaji":"Hito no heya ni katte ni haitte wa ikemasen.","meaning":"You must not enter someone's room without permission."}]},{"jlpt_level":"N4","sort_order":8,"additional_examples":[{"japanese":"そんなに急がないでください。","romaji":"Sonna ni isoganaide kudasai.","meaning":"Please do not rush so much."},{"japanese":"まだ帰らないで。","romaji":"Mada kaeranaide.","meaning":"Please do not go home yet."},{"japanese":"このことを忘れないでください。","romaji":"Kono koto o wasurenaide kudasai.","meaning":"Please do not forget this."},{"japanese":"一人で決めないで、相談してください。","romaji":"Hitori de kimenaide, soudan shite kudasai.","meaning":"Do not decide by yourself; please talk it over."}]},{"jlpt_level":"N4","sort_order":9,"additional_examples":[{"japanese":"北海道へ行ったことがあります。","romaji":"Hokkaidou e itta koto ga arimasu.","meaning":"I have been to Hokkaido."},{"japanese":"一人で料理を作ったことがあります。","romaji":"Hitori de ryouri o tsukutta koto ga arimasu.","meaning":"I have cooked by myself before."},{"japanese":"日本の温泉に入ったことがあります。","romaji":"Nihon no onsen ni haitta koto ga arimasu.","meaning":"I have been in a Japanese hot spring."},{"japanese":"この映画を見たことがあります。","romaji":"Kono eiga o mita koto ga arimasu.","meaning":"I have seen this movie before."}]},{"jlpt_level":"N4","sort_order":10,"additional_examples":[{"japanese":"馬に乗ったことがありません。","romaji":"Uma ni notta koto ga arimasen.","meaning":"I have never ridden a horse."},{"japanese":"海外で生活したことがありません。","romaji":"Kaigai de seikatsu shita koto ga arimasen.","meaning":"I have never lived abroad."},{"japanese":"納豆を食べたことがありません。","romaji":"Nattou o tabeta koto ga arimasen.","meaning":"I have never eaten natto."},{"japanese":"一人で飛行機に乗ったことがありません。","romaji":"Hitori de hikouki ni notta koto ga arimasen.","meaning":"I have never flown alone."}]},{"jlpt_level":"N4","sort_order":11,"additional_examples":[{"japanese":"今年は毎日運動するつもりです。","romaji":"Kotoshi wa mainichi undou suru tsumori desu.","meaning":"I intend to exercise every day this year."},{"japanese":"週末は家でゆっくり休むつもりです。","romaji":"Shuumatsu wa ie de yukkuri yasumu tsumori desu.","meaning":"I plan to relax at home this weekend."},{"japanese":"卒業したら、日本で働くつもりです。","romaji":"Sotsugyou shitara, Nihon de hataraku tsumori desu.","meaning":"After I graduate, I intend to work in Japan."},{"japanese":"今日は何も買わないつもりです。","romaji":"Kyou wa nani mo kawanai tsumori desu.","meaning":"I do not intend to buy anything today."}]},{"jlpt_level":"N4","sort_order":12,"additional_examples":[{"japanese":"来月、新しいアパートに引っ越す予定です。","romaji":"Raigetsu, atarashii apaato ni hikkosu yotei desu.","meaning":"I plan to move to a new apartment next month."},{"japanese":"会議は午後三時に始まる予定です。","romaji":"Kaigi wa gogo san-ji ni hajimaru yotei desu.","meaning":"The meeting is scheduled to start at three in the afternoon."},{"japanese":"夏休みに家族と旅行する予定です。","romaji":"Natsuyasumi ni kazoku to ryokou suru yotei desu.","meaning":"I plan to travel with my family during summer vacation."},{"japanese":"電車はあと十分で到着する予定です。","romaji":"Densha wa ato juppun de touchaku suru yotei desu.","meaning":"The train is scheduled to arrive in ten minutes."}]},{"jlpt_level":"N4","sort_order":13,"additional_examples":[{"japanese":"来年、日本へ留学しようと思っています。","romaji":"Rainen, Nihon e ryuugaku shiyou to omotte imasu.","meaning":"I am thinking of studying in Japan next year."},{"japanese":"週末は部屋を掃除しようと思います。","romaji":"Shuumatsu wa heya o souji shiyou to omoimasu.","meaning":"I think I will clean my room this weekend."},{"japanese":"健康のために、毎朝歩こうと思っています。","romaji":"Kenkou no tame ni, maiasa arukou to omotte imasu.","meaning":"I am thinking of walking every morning for my health."},{"japanese":"今日は早く寝ようと思います。","romaji":"Kyou wa hayaku neyou to omoimasu.","meaning":"I think I will go to bed early today."}]},{"jlpt_level":"N4","sort_order":14,"additional_examples":[{"japanese":"日本で働くために、日本語を勉強しています。","romaji":"Nihon de hataraku tame ni, nihongo o benkyou shite imasu.","meaning":"I am studying Japanese in order to work in Japan."},{"japanese":"家を買うために、お金を貯めています。","romaji":"Ie o kau tame ni, okane o tamete imasu.","meaning":"I am saving money in order to buy a house."},{"japanese":"試験に合格するために、毎晩復習します。","romaji":"Shiken ni goukaku suru tame ni, maiban fukushuu shimasu.","meaning":"I review every night in order to pass the exam."},{"japanese":"健康のために、野菜をたくさん食べています。","romaji":"Kenkou no tame ni, yasai o takusan tabete imasu.","meaning":"I eat a lot of vegetables for my health."}]},{"jlpt_level":"N4","sort_order":15,"additional_examples":[{"japanese":"忘れないように、手帳に書いておきます。","romaji":"Wasurenai you ni, techou ni kaite okimasu.","meaning":"I write it in my planner so that I will not forget."},{"japanese":"よく聞こえるように、前の席に座りました。","romaji":"Yoku kikoeru you ni, mae no seki ni suwarimashita.","meaning":"I sat in the front seat so that I could hear well."},{"japanese":"遅れないように、早く家を出ます。","romaji":"Okurenai you ni, hayaku ie o demasu.","meaning":"I leave home early so that I will not be late."},{"japanese":"みんなに分かるように、ゆっくり説明します。","romaji":"Minna ni wakaru you ni, yukkuri setsumei shimasu.","meaning":"I will explain slowly so that everyone can understand."}]},{"jlpt_level":"N4","sort_order":16,"additional_examples":[{"japanese":"毎朝六時に起きることにしました。","romaji":"Maiasa roku-ji ni okiru koto ni shimashita.","meaning":"I have decided to get up at six every morning."},{"japanese":"甘い物をあまり食べないことにしました。","romaji":"Amai mono o amari tabenai koto ni shimashita.","meaning":"I have decided not to eat many sweets."},{"japanese":"来月から電車で通勤することにします。","romaji":"Raigetsu kara densha de tsuukin suru koto ni shimasu.","meaning":"I will decide to commute by train starting next month."},{"japanese":"今年は毎週本を一冊読むことにしました。","romaji":"Kotoshi wa maishuu hon o issatsu yomu koto ni shimashita.","meaning":"I have decided to read one book every week this year."}]},{"jlpt_level":"N4","sort_order":17,"additional_examples":[{"japanese":"電車が遅れているので、少し待ちましょう。","romaji":"Densha ga okurete iru node, sukoshi machimashou.","meaning":"The train is delayed, so let's wait a little."},{"japanese":"今日は日曜日なので、銀行は休みです。","romaji":"Kyou wa nichiyoubi na node, ginkou wa yasumi desu.","meaning":"Because today is Sunday, the bank is closed."},{"japanese":"道が混んでいるので、バスで行きます。","romaji":"Michi ga konde iru node, basu de ikimasu.","meaning":"Because the road is busy, I will go by bus."},{"japanese":"頭が痛いので、早く帰ります。","romaji":"Atama ga itai node, hayaku kaerimasu.","meaning":"Because I have a headache, I will go home early."}]},{"jlpt_level":"N4","sort_order":18,"additional_examples":[{"japanese":"どうしたんですか。顔色が悪いですよ。","romaji":"Dou shita n desu ka. Kaoiro ga warui desu yo.","meaning":"What happened? You look pale."},{"japanese":"今日は早く帰るんです。","romaji":"Kyou wa hayaku kaeru n desu.","meaning":"The thing is, I am going home early today."},{"japanese":"駅まで歩いてきたんです。","romaji":"Eki made aruite kita n desu.","meaning":"I walked here from the station, you see."},{"japanese":"この漢字は何と読むんですか。","romaji":"Kono kanji wa nan to yomu n desu ka.","meaning":"How do you read this kanji?"}]},{"jlpt_level":"N4","sort_order":19,"additional_examples":[{"japanese":"早く出たのに、電車に間に合いませんでした。","romaji":"Hayaku deta noni, densha ni maniaimasen deshita.","meaning":"Although I left early, I did not make the train."},{"japanese":"薬を飲んだのに、まだ熱があります。","romaji":"Kusuri o nonda noni, mada netsu ga arimasu.","meaning":"Although I took medicine, I still have a fever."},{"japanese":"一生懸命勉強したのに、試験に落ちました。","romaji":"Isshoukenmei benkyou shita noni, shiken ni ochimashita.","meaning":"Although I studied very hard, I failed the exam."},{"japanese":"約束したのに、彼は来ませんでした。","romaji":"Yakusoku shita noni, kare wa kimasen deshita.","meaning":"Even though he promised, he did not come."}]},{"jlpt_level":"N4","sort_order":20,"additional_examples":[{"japanese":"行きたいけれども、今日は時間がありません。","romaji":"Ikitai keredomo, kyou wa jikan ga arimasen.","meaning":"I want to go, but I do not have time today."},{"japanese":"この店は少し高いけれども、おいしいです。","romaji":"Kono mise wa sukoshi takai keredomo, oishii desu.","meaning":"This shop is a little expensive, but the food is delicious."},{"japanese":"雨が降っているけれども、出かけます。","romaji":"Ame ga futte iru keredomo, dekakemasu.","meaning":"It is raining, but I will go out."},{"japanese":"日本語は難しいけれども、勉強するのが楽しいです。","romaji":"Nihongo wa muzukashii keredomo, benkyou suru no ga tanoshii desu.","meaning":"Japanese is difficult, but studying it is fun."}]},{"jlpt_level":"N4","sort_order":21,"additional_examples":[{"japanese":"この本は長いですが、とてもおもしろいです。","romaji":"Kono hon wa nagai desu ga, totemo omoshiroi desu.","meaning":"This book is long, but it is very interesting."},{"japanese":"彼は若いですが、経験が豊富です。","romaji":"Kare wa wakai desu ga, keiken ga houfu desu.","meaning":"He is young, but he has a lot of experience."},{"japanese":"駅から遠いですが、歩いて行けます。","romaji":"Eki kara tooi desu ga, aruite ikemasu.","meaning":"It is far from the station, but we can walk there."},{"japanese":"日本語を勉強していますが、まだ上手に話せません。","romaji":"Nihongo o benkyou shite imasu ga, mada jouzu ni hanasemasen.","meaning":"I am studying Japanese, but I still cannot speak it well."}]},{"jlpt_level":"N4","sort_order":22,"additional_examples":[{"japanese":"この町は静かだし、緑も多いし、住みやすいです。","romaji":"Kono machi wa shizuka da shi, midori mo ooi shi, sumiyasui desu.","meaning":"This town is quiet and has lots of greenery, so it is pleasant to live in."},{"japanese":"彼は親切だし、仕事も速いです。","romaji":"Kare wa shinsetsu da shi, shigoto mo hayai desu.","meaning":"He is kind, and he also works quickly."},{"japanese":"この部屋は広いし、駅にも近いです。","romaji":"Kono heya wa hiroi shi, eki ni mo chikai desu.","meaning":"This room is spacious, and it is also close to the station."},{"japanese":"雨も降っているし、風も強いので、出かけません。","romaji":"Ame mo futte iru shi, kaze mo tsuyoi node, dekakemasen.","meaning":"It is raining and the wind is strong, so I will not go out."}]},{"jlpt_level":"N4","sort_order":23,"additional_examples":[{"japanese":"週末は映画を見たり、買い物をしたりします。","romaji":"Shuumatsu wa eiga o mitari, kaimono o shitari shimasu.","meaning":"On weekends, I do things like watch movies and go shopping."},{"japanese":"休みの日は本を読んだり、音楽を聞いたりします。","romaji":"Yasumi no hi wa hon o yondari, ongaku o kiitari shimasu.","meaning":"On days off, I do things like read books and listen to music."},{"japanese":"昨日は友達と話したり、写真を撮ったりしました。","romaji":"Kinou wa tomodachi to hanashitari, shashin o tottari shimashita.","meaning":"Yesterday, I did things like talk with friends and take photos."},{"japanese":"旅行ではおいしい物を食べたり、お寺を見たりしました。","romaji":"Ryokou de wa oishii mono o tabetari, otera o mitari shimashita.","meaning":"On the trip, I did things like eat delicious food and visit temples."}]},{"jlpt_level":"N4","sort_order":24,"additional_examples":[{"japanese":"熱があるから、今日は学校を休みます。","romaji":"Netsu ga aru kara, kyou wa gakkou o yasumimasu.","meaning":"Because I have a fever, I will stay home from school today."},{"japanese":"時間がないから、タクシーで行きます。","romaji":"Jikan ga nai kara, takushii de ikimasu.","meaning":"Because I do not have time, I will go by taxi."},{"japanese":"明日は早いから、もう寝ます。","romaji":"Ashita wa hayai kara, mou nemasu.","meaning":"Because I have to get up early tomorrow, I am going to bed now."},{"japanese":"この店は安いから、よく来ます。","romaji":"Kono mise wa yasui kara, yoku kimasu.","meaning":"Because this shop is inexpensive, I come here often."}]},{"jlpt_level":"N4","sort_order":25,"additional_examples":[{"japanese":"大雨のため、電車が止まりました。","romaji":"Ooame no tame, densha ga tomarimashita.","meaning":"The trains stopped because of the heavy rain."},{"japanese":"工事のため、この道は通れません。","romaji":"Kouji no tame, kono michi wa tooremasen.","meaning":"This road is closed because of construction."},{"japanese":"事故のため、会議に遅れました。","romaji":"Jiko no tame, kaigi ni okuremashita.","meaning":"I was late for the meeting because of an accident."},{"japanese":"病気のため、しばらく休みます。","romaji":"Byouki no tame, shibaraku yasumimasu.","meaning":"I will take a break for a while because of illness."}]},{"jlpt_level":"N4","sort_order":26,"additional_examples":[{"japanese":"子どもが寝ている間、母は本を読んでいました。","romaji":"Kodomo ga nete iru aida, haha wa hon o yonde imashita.","meaning":"While the child was sleeping, the mother was reading a book."},{"japanese":"夏休みの間、毎日プールで泳ぎました。","romaji":"Natsuyasumi no aida, mainichi puuru de oyogimashita.","meaning":"I swam in the pool every day during summer vacation."},{"japanese":"会議の間、携帯電話を切ってください。","romaji":"Kaigi no aida, keitai denwa o kitte kudasai.","meaning":"Please turn off your mobile phone during the meeting."},{"japanese":"留守の間、隣の人が犬の世話をしてくれました。","romaji":"Rusu no aida, tonari no hito ga inu no sewa o shite kuremashita.","meaning":"While I was away, the neighbour looked after my dog."}]},{"jlpt_level":"N4","sort_order":27,"additional_examples":[{"japanese":"留守の間に、荷物が届きました。","romaji":"Rusu no aida ni, nimotsu ga todokimashita.","meaning":"A package arrived while I was away."},{"japanese":"私が寝ている間に、雨が止みました。","romaji":"Watashi ga nete iru aida ni, ame ga yamimashita.","meaning":"The rain stopped while I was sleeping."},{"japanese":"旅行している間に、友達から手紙が来ました。","romaji":"Ryokou shite iru aida ni, tomodachi kara tegami ga kimashita.","meaning":"A letter arrived from my friend while I was travelling."},{"japanese":"会議の間に、電話が三回ありました。","romaji":"Kaigi no aida ni, denwa ga san-kai arimashita.","meaning":"There were three phone calls during the meeting."}]},{"jlpt_level":"N4","sort_order":28,"additional_examples":[{"japanese":"音楽を聞きながら、料理を作ります。","romaji":"Ongaku o kikinagara, ryouri o tsukurimasu.","meaning":"I cook while listening to music."},{"japanese":"歩きながらスマートフォンを見ないでください。","romaji":"Arukinagara sumaatofon o minaide kudasai.","meaning":"Please do not look at your smartphone while walking."},{"japanese":"コーヒーを飲みながら、新聞を読みました。","romaji":"Koohii o nominagara, shinbun o yomimashita.","meaning":"I read the newspaper while drinking coffee."},{"japanese":"友達と話しながら、駅まで歩きました。","romaji":"Tomodachi to hanashinagara, eki made arukimashita.","meaning":"I walked to the station while talking with a friend."}]},{"jlpt_level":"N4","sort_order":29,"additional_examples":[{"japanese":"旅行の前にホテルを予約しておきます。","romaji":"Ryokou no mae ni hoteru o yoyaku shite okimasu.","meaning":"I will book the hotel in advance before the trip."},{"japanese":"会議の資料を先に印刷しておいてください。","romaji":"Kaigi no shiryou o saki ni insatsu shite oite kudasai.","meaning":"Please print the meeting materials beforehand."},{"japanese":"お客さんが来るので、部屋を掃除しておきました。","romaji":"Okyakusan ga kuru node, heya o souji shite okimashita.","meaning":"I cleaned the room in advance because guests are coming."},{"japanese":"後で使うので、この箱に入れておきます。","romaji":"Ato de tsukau node, kono hako ni irete okimasu.","meaning":"I will put it in this box because I will use it later."}]},{"jlpt_level":"N4","sort_order":30,"additional_examples":[{"japanese":"財布を家に忘れてしまいました。","romaji":"Saifu o ie ni wasurete shimaimashita.","meaning":"I accidentally left my wallet at home."},{"japanese":"大切な写真を消してしまいました。","romaji":"Taisetsu na shashin o keshite shimaimashita.","meaning":"I accidentally deleted an important photo."},{"japanese":"ケーキを全部食べてしまいました。","romaji":"Keeki o zenbu tabete shimaimashita.","meaning":"I ate all the cake."},{"japanese":"電車の中で寝てしまいました。","romaji":"Densha no naka de nete shimaimashita.","meaning":"I fell asleep on the train."}]},{"jlpt_level":"N4","sort_order":31,"additional_examples":[{"japanese":"この服を着てみてもいいですか。","romaji":"Kono fuku o kite mite mo ii desu ka.","meaning":"May I try this outfit on?"},{"japanese":"日本の料理を作ってみました。","romaji":"Nihon no ryouri o tsukutte mimashita.","meaning":"I tried making Japanese food."},{"japanese":"分からない言葉を辞書で調べてみてください。","romaji":"Wakaranai kotoba o jisho de shirabete mite kudasai.","meaning":"Please try looking up words you do not understand in a dictionary."},{"japanese":"新しい道を通ってみましょう。","romaji":"Atarashii michi o tootte mimashou.","meaning":"Let's try taking the new road."}]},{"jlpt_level":"N4","sort_order":32,"additional_examples":[{"japanese":"予定表が壁に貼ってあります。","romaji":"Yoteihyou ga kabe ni hatte arimasu.","meaning":"The schedule has been put up on the wall."},{"japanese":"テーブルの上に料理が並べてあります。","romaji":"Teeburu no ue ni ryouri ga narabete arimasu.","meaning":"The food has been laid out on the table."},{"japanese":"窓が開けてあります。","romaji":"Mado ga akete arimasu.","meaning":"The window has been left open."},{"japanese":"会議室に椅子が用意してあります。","romaji":"Kaigishitsu ni isu ga youi shite arimasu.","meaning":"Chairs have been prepared in the meeting room."}]},{"jlpt_level":"N4","sort_order":33,"additional_examples":[{"japanese":"母は今、夕食を作っています。","romaji":"Haha wa ima, yuushoku o tsukutte imasu.","meaning":"My mother is making dinner now."},{"japanese":"弟は部屋で勉強しています。","romaji":"Otouto wa heya de benkyou shite imasu.","meaning":"My younger brother is studying in his room."},{"japanese":"外では子どもたちが遊んでいます。","romaji":"Soto de wa kodomotachi ga asonde imasu.","meaning":"The children are playing outside."},{"japanese":"先生は黒板に漢字を書いています。","romaji":"Sensei wa kokuban ni kanji o kaite imasu.","meaning":"The teacher is writing kanji on the blackboard."}]},{"jlpt_level":"N4","sort_order":34,"additional_examples":[{"japanese":"これからも日本語を勉強していきます。","romaji":"Kore kara mo nihongo o benkyou shite ikimasu.","meaning":"I will continue studying Japanese from now on."},{"japanese":"町の人口はこれから増えていくでしょう。","romaji":"Machi no jinkou wa kore kara fuete iku deshou.","meaning":"The town's population will probably continue to increase."},{"japanese":"少しずつ生活に慣れていきたいです。","romaji":"Sukoshi zutsu seikatsu ni narete ikitai desu.","meaning":"I want to gradually get used to life here."},{"japanese":"この伝統を次の世代に伝えていきます。","romaji":"Kono dentou o tsugi no sedai ni tsutaete ikimasu.","meaning":"We will pass this tradition on to the next generation."}]},{"jlpt_level":"N4","sort_order":35,"additional_examples":[{"japanese":"最近、朝晩は寒くなってきました。","romaji":"Saikin, asaban wa samuku natte kimashita.","meaning":"Recently, mornings and evenings have become cold."},{"japanese":"日本語のニュースが少し分かってきました。","romaji":"Nihongo no nyuusu ga sukoshi wakatte kimashita.","meaning":"I have started to understand Japanese news a little."},{"japanese":"雨が強くなってきました。","romaji":"Ame ga tsuyoku natte kimashita.","meaning":"The rain has become heavier."},{"japanese":"駅の近くに新しい店ができてきました。","romaji":"Eki no chikaku ni atarashii mise ga dekite kimashita.","meaning":"New shops have started appearing near the station."}]},{"jlpt_level":"N4","sort_order":36,"additional_examples":[{"japanese":"毎日練習して、漢字が読めるようになりました。","romaji":"Mainichi renshuu shite, kanji ga yomeru you ni narimashita.","meaning":"After practising every day, I became able to read kanji."},{"japanese":"妹は一人で料理できるようになりました。","romaji":"Imouto wa hitori de ryouri dekiru you ni narimashita.","meaning":"My younger sister has become able to cook by herself."},{"japanese":"最近、早く起きられるようになりました。","romaji":"Saikin, hayaku okirareru you ni narimashita.","meaning":"Recently, I have become able to get up early."},{"japanese":"日本語で簡単な会話ができるようになりました。","romaji":"Nihongo de kantan na kaiwa ga dekiru you ni narimashita.","meaning":"I have become able to have simple conversations in Japanese."}]},{"jlpt_level":"N4","sort_order":37,"additional_examples":[{"japanese":"健康のために、毎日歩くようにしています。","romaji":"Kenkou no tame ni, mainichi aruku you ni shite imasu.","meaning":"I make a point of walking every day for my health."},{"japanese":"忘れ物をしないように、前の日に準備するようにしています。","romaji":"Wasuremono o shinai you ni, mae no hi ni junbi suru you ni shite imasu.","meaning":"I make a point of preparing the day before so I do not forget things."},{"japanese":"できるだけ日本語で話すようにしています。","romaji":"Dekiru dake nihongo de hanasu you ni shite imasu.","meaning":"I try to speak Japanese as much as possible."},{"japanese":"夜遅くコーヒーを飲まないようにしています。","romaji":"Yoru osoku koohii o nomanai you ni shite imasu.","meaning":"I make a point of not drinking coffee late at night."}]},{"jlpt_level":"N4","sort_order":38,"additional_examples":[{"japanese":"来月から大阪で働くことになりました。","romaji":"Raigetsu kara Osaka de hataraku koto ni narimashita.","meaning":"It has been decided that I will work in Osaka from next month."},{"japanese":"来週、東京へ出張することになりました。","romaji":"Raishuu, Tokyo e shutchou suru koto ni narimashita.","meaning":"It has been decided that I will go on a business trip to Tokyo next week."},{"japanese":"会議はオンラインで行うことになりました。","romaji":"Kaigi wa onrain de okonau koto ni narimashita.","meaning":"It has been decided that the meeting will be held online."},{"japanese":"今年から新しい先生が担当することになりました。","romaji":"Kotoshi kara atarashii sensei ga tantou suru koto ni narimashita.","meaning":"It has been decided that a new teacher will be in charge from this year."}]},{"jlpt_level":"N4","sort_order":39,"additional_examples":[{"japanese":"寝る前にスマートフォンを見ないことにしています。","romaji":"Neru mae ni sumaatofon o minai koto ni shite imasu.","meaning":"I make it a rule not to look at my smartphone before bed."},{"japanese":"毎朝、新聞を読むことにしています。","romaji":"Maiasa, shinbun o yomu koto ni shite imasu.","meaning":"I make it a rule to read the newspaper every morning."},{"japanese":"健康のために、階段を使うことにしています。","romaji":"Kenkou no tame ni, kaidan o tsukau koto ni shite imasu.","meaning":"I make it a rule to use the stairs for my health."},{"japanese":"週末は家族と食事をすることにしています。","romaji":"Shuumatsu wa kazoku to shokuji o suru koto ni shite imasu.","meaning":"I make it a rule to have meals with my family on weekends."}]},{"jlpt_level":"N4","sort_order":40,"additional_examples":[{"japanese":"先生は学生に毎日漢字を書くように言いました。","romaji":"Sensei wa gakusei ni mainichi kanji o kaku you ni iimashita.","meaning":"The teacher told the students to write kanji every day."},{"japanese":"母は私に早く帰るように言いました。","romaji":"Haha wa watashi ni hayaku kaeru you ni iimashita.","meaning":"My mother told me to come home early."},{"japanese":"医者は父にお酒を飲まないように言いました。","romaji":"Isha wa chichi ni osake o nomanai you ni iimashita.","meaning":"The doctor told my father not to drink alcohol."},{"japanese":"上司は私に資料を準備するように言いました。","romaji":"Joushi wa watashi ni shiryou o junbi suru you ni iimashita.","meaning":"My supervisor told me to prepare the materials."}]},{"jlpt_level":"N4","sort_order":41,"additional_examples":[{"japanese":"早く宿題をしなさい。","romaji":"Hayaku shukudai o shinasai.","meaning":"Do your homework soon."},{"japanese":"部屋をきれいにしなさい。","romaji":"Heya o kirei ni shinasai.","meaning":"Clean your room."},{"japanese":"困ったときは先生に聞きなさい。","romaji":"Komatta toki wa sensei ni kikinasai.","meaning":"Ask the teacher when you have trouble."},{"japanese":"野菜もちゃんと食べなさい。","romaji":"Yasai mo chanto tabenasai.","meaning":"Make sure you eat your vegetables too."}]},{"jlpt_level":"N4","sort_order":42,"additional_examples":[{"japanese":"疲れているなら、少し休んだほうがいいです。","romaji":"Tsukarete iru nara, sukoshi yasunda hou ga ii desu.","meaning":"If you are tired, you should rest a little."},{"japanese":"風邪をひいたときは、早く寝たほうがいいです。","romaji":"Kaze o hiita toki wa, hayaku neta hou ga ii desu.","meaning":"When you catch a cold, you should go to bed early."},{"japanese":"分からない言葉は辞書で調べたほうがいいです。","romaji":"Wakaranai kotoba wa jisho de shirabeta hou ga ii desu.","meaning":"You should look up words you do not understand in a dictionary."},{"japanese":"大切な書類はコピーを取ったほうがいいです。","romaji":"Taisetsu na shorui wa kopii o totta hou ga ii desu.","meaning":"You should make a copy of important documents."}]},{"jlpt_level":"N4","sort_order":43,"additional_examples":[{"japanese":"夜遅くコーヒーを飲まないほうがいいです。","romaji":"Yoru osoku koohii o nomanai hou ga ii desu.","meaning":"You should not drink coffee late at night."},{"japanese":"具合が悪いときは無理をしないほうがいいです。","romaji":"Guai ga warui toki wa muri o shinai hou ga ii desu.","meaning":"When you feel unwell, you should not push yourself."},{"japanese":"雨の日は運転しないほうがいいです。","romaji":"Ame no hi wa unten shinai hou ga ii desu.","meaning":"You should not drive on rainy days."},{"japanese":"試験の前に夜更かしをしないほうがいいです。","romaji":"Shiken no mae ni yofukashi o shinai hou ga ii desu.","meaning":"You should not stay up late before an exam."}]},{"jlpt_level":"N4","sort_order":44,"additional_examples":[{"japanese":"約束したことは守るべきです。","romaji":"Yakusoku shita koto wa mamoru beki desu.","meaning":"You should keep your promises."},{"japanese":"困っている人を助けるべきです。","romaji":"Komatte iru hito o tasukeru beki desu.","meaning":"You ought to help people who are in trouble."},{"japanese":"環境を大切にするべきです。","romaji":"Kankyou o taisetsu ni suru beki desu.","meaning":"We should take care of the environment."},{"japanese":"自分の意見をはっきり伝えるべきです。","romaji":"Jibun no iken o hakkiri tsutaeru beki desu.","meaning":"You ought to express your opinion clearly."}]},{"jlpt_level":"N4","sort_order":45,"additional_examples":[{"japanese":"時間があれば、手伝います。","romaji":"Jikan ga areba, tetsudaimasu.","meaning":"If I have time, I will help."},{"japanese":"安ければ、そのかばんを買います。","romaji":"Yasukereba, sono kaban o kaimasu.","meaning":"If it is inexpensive, I will buy that bag."},{"japanese":"毎日練習すれば、上手になります。","romaji":"Mainichi renshuu sureba, jouzu ni narimasu.","meaning":"If you practise every day, you will improve."},{"japanese":"駅に近ければ、そこに住みたいです。","romaji":"Eki ni chikakereba, soko ni sumitai desu.","meaning":"If it is near the station, I would like to live there."}]},{"jlpt_level":"N4","sort_order":46,"additional_examples":[{"japanese":"家に帰ったら、すぐ電話してください。","romaji":"Ie ni kaettara, sugu denwa shite kudasai.","meaning":"When you get home, please call me right away."},{"japanese":"駅に着いたら、連絡します。","romaji":"Eki ni tsuitara, renraku shimasu.","meaning":"I will contact you when I arrive at the station."},{"japanese":"雨が降ったら、試合は中止です。","romaji":"Ame ga futtara, shiai wa chuushi desu.","meaning":"If it rains, the match will be cancelled."},{"japanese":"仕事が終わったら、一緒に食事しましょう。","romaji":"Shigoto ga owattara, issho ni shokuji shimashou.","meaning":"When work is over, let's have a meal together."}]},{"jlpt_level":"N4","sort_order":47,"additional_examples":[{"japanese":"日本へ旅行するなら、春がおすすめです。","romaji":"Nihon e ryokou suru nara, haru ga osusume desu.","meaning":"If you are travelling to Japan, spring is recommended."},{"japanese":"車を買うなら、この店がいいですよ。","romaji":"Kuruma o kau nara, kono mise ga ii desu yo.","meaning":"If you are buying a car, this shop is a good choice."},{"japanese":"時間がないなら、タクシーで行きましょう。","romaji":"Jikan ga nai nara, takushii de ikimashou.","meaning":"If you do not have time, let's take a taxi."},{"japanese":"京都へ行くなら、お寺を見たほうがいいです。","romaji":"Kyoto e iku nara, otera o mita hou ga ii desu.","meaning":"If you go to Kyoto, you should visit the temples."}]},{"jlpt_level":"N4","sort_order":48,"additional_examples":[{"japanese":"このボタンを押すと、ドアが開きます。","romaji":"Kono botan o osu to, doa ga akimasu.","meaning":"When you press this button, the door opens."},{"japanese":"春になると、桜が咲きます。","romaji":"Haru ni naru to, sakura ga sakimasu.","meaning":"When spring comes, cherry blossoms bloom."},{"japanese":"右に曲がると、駅があります。","romaji":"Migi ni magaru to, eki ga arimasu.","meaning":"If you turn right, there is a station."},{"japanese":"この薬を飲むと、眠くなります。","romaji":"Kono kusuri o nomu to, nemuku narimasu.","meaning":"When you take this medicine, you become sleepy."}]},{"jlpt_level":"N4","sort_order":49,"additional_examples":[{"japanese":"雨が降っても、試合は続きます。","romaji":"Ame ga futte mo, shiai wa tsuzukimasu.","meaning":"Even if it rains, the match will continue."},{"japanese":"忙しくても、毎日運動します。","romaji":"Isogashikute mo, mainichi undou shimasu.","meaning":"Even when I am busy, I exercise every day."},{"japanese":"高くても、このカメラを買いたいです。","romaji":"Takakute mo, kono kamera o kaitai desu.","meaning":"Even if it is expensive, I want to buy this camera."},{"japanese":"何回読んでも、意味が分かりません。","romaji":"Nankai yonde mo, imi ga wakarimasen.","meaning":"No matter how many times I read it, I do not understand the meaning."}]},{"jlpt_level":"N4","sort_order":50,"additional_examples":[{"japanese":"雨の場合は、試合を中止します。","romaji":"Ame no baai wa, shiai o chuushi shimasu.","meaning":"In the case of rain, we will cancel the match."},{"japanese":"火事の場合は、非常口から逃げてください。","romaji":"Kaji no baai wa, hijouguchi kara nigete kudasai.","meaning":"In case of fire, please escape through the emergency exit."},{"japanese":"分からない場合は、係の人に聞いてください。","romaji":"Wakaranai baai wa, kakari no hito ni kiite kudasai.","meaning":"If you do not understand, please ask the staff member."},{"japanese":"遅れる場合は、先に連絡してください。","romaji":"Okureru baai wa, saki ni renraku shite kudasai.","meaning":"If you will be late, please contact us in advance."}]},{"jlpt_level":"N4","sort_order":51,"additional_examples":[{"japanese":"この歌を聞くたびに、学生時代を思い出します。","romaji":"Kono uta o kiku tabi ni, gakusei jidai o omoidasu.","meaning":"Every time I hear this song, I remember my student days."},{"japanese":"この写真を見るたびに、家族に会いたくなります。","romaji":"Kono shashin o miru tabi ni, kazoku ni aitaku narimasu.","meaning":"Every time I look at this photo, I miss my family."},{"japanese":"彼に会うたびに、新しい話を聞きます。","romaji":"Kare ni au tabi ni, atarashii hanashi o kikimasu.","meaning":"Every time I meet him, I hear a new story."},{"japanese":"この道を通るたびに、昔のことを思い出します。","romaji":"Kono michi o tooru tabi ni, mukashi no koto o omoidasu.","meaning":"Every time I pass this road, I remember the past."}]},{"jlpt_level":"N4","sort_order":52,"additional_examples":[{"japanese":"先生のおかげで、試験に合格できました。","romaji":"Sensei no okage de, shiken ni goukaku dekimashita.","meaning":"Thanks to the teacher, I was able to pass the exam."},{"japanese":"友達が手伝ってくれたおかげで、早く終わりました。","romaji":"Tomodachi ga tetsudatte kureta okage de, hayaku owarimashita.","meaning":"Thanks to my friend's help, I finished early."},{"japanese":"毎日練習したおかげで、泳げるようになりました。","romaji":"Mainichi renshuu shita okage de, oyogeru you ni narimashita.","meaning":"Thanks to practising every day, I became able to swim."},{"japanese":"天気がよかったおかげで、楽しい旅行になりました。","romaji":"Tenki ga yokatta okage de, tanoshii ryokou ni narimashita.","meaning":"Thanks to the good weather, it became an enjoyable trip."}]},{"jlpt_level":"N4","sort_order":53,"additional_examples":[{"japanese":"渋滞のせいで、会議に遅れました。","romaji":"Juutai no sei de, kaigi ni okuremashita.","meaning":"I was late for the meeting because of traffic."},{"japanese":"寝不足のせいで、頭が痛いです。","romaji":"Nebusoku no sei de, atama ga itai desu.","meaning":"My head hurts because I did not get enough sleep."},{"japanese":"雨のせいで、服がぬれてしまいました。","romaji":"Ame no sei de, fuku ga nurete shimaimashita.","meaning":"My clothes got wet because of the rain."},{"japanese":"彼の説明が足りなかったせいで、みんなが困りました。","romaji":"Kare no setsumei ga tarinakatta sei de, minna ga komarimashita.","meaning":"Everyone was confused because his explanation was insufficient."}]},{"jlpt_level":"N4","sort_order":54,"additional_examples":[{"japanese":"電車のかわりに、バスで行きました。","romaji":"Densha no kawari ni, basu de ikimashita.","meaning":"I went by bus instead of by train."},{"japanese":"砂糖のかわりに、はちみつを入れます。","romaji":"Satou no kawari ni, hachimitsu o iremasu.","meaning":"I add honey instead of sugar."},{"japanese":"今日は私が運転するかわりに、あなたが道を調べてください。","romaji":"Kyou wa watashi ga unten suru kawari ni, anata ga michi o shirabete kudasai.","meaning":"Today, I will drive, so please look up the route in return."},{"japanese":"歩くかわりに、自転車で通っています。","romaji":"Aruku kawari ni, jitensha de kayotte imasu.","meaning":"I commute by bicycle instead of walking."}]},{"jlpt_level":"N4","sort_order":55,"additional_examples":[{"japanese":"説明書に書いてあるとおりに、組み立ててください。","romaji":"Setsumeisho ni kaite aru toori ni, kumitatete kudasai.","meaning":"Please assemble it exactly as written in the instructions."},{"japanese":"先生が言ったとおりに、答えを書きました。","romaji":"Sensei ga itta toori ni, kotae o kakimashita.","meaning":"I wrote the answer just as the teacher said."},{"japanese":"地図のとおりに進んでください。","romaji":"Chizu no toori ni susunde kudasai.","meaning":"Please proceed according to the map."},{"japanese":"予定どおりに、会議が始まりました。","romaji":"Yotei doori ni, kaigi ga hajimarimashita.","meaning":"The meeting started as scheduled."}]},{"jlpt_level":"N4","sort_order":56,"additional_examples":[{"japanese":"電気をつけたまま、出かけてしまいました。","romaji":"Denki o tsuketa mama, dekakete shimaimashita.","meaning":"I went out and left the lights on."},{"japanese":"窓を開けたまま寝てしまいました。","romaji":"Mado o aketa mama nete shimaimashita.","meaning":"I fell asleep with the window left open."},{"japanese":"靴をはいたまま、部屋に入らないでください。","romaji":"Kutsu o haita mama, heya ni hairanaide kudasai.","meaning":"Please do not enter the room with your shoes on."},{"japanese":"テレビをつけたまま勉強しています。","romaji":"Terebi o tsuketa mama benkyou shite imasu.","meaning":"I am studying with the television left on."}]},{"jlpt_level":"N4","sort_order":57,"additional_examples":[{"japanese":"暗くならないうちに、帰りましょう。","romaji":"Kuraku naranai uchi ni, kaerimashou.","meaning":"Let's go home before it gets dark."},{"japanese":"若いうちに、いろいろな経験をしたほうがいいです。","romaji":"Wakai uchi ni, iroiro na keiken o shita hou ga ii desu.","meaning":"You should have various experiences while you are young."},{"japanese":"忘れないうちに、メモをしておきます。","romaji":"Wasurenai uchi ni, memo o shite okimasu.","meaning":"I will make a note before I forget."},{"japanese":"雨が降らないうちに、洗濯物を取り込みます。","romaji":"Ame ga furanai uchi ni, sentakumono o torikomimasu.","meaning":"I will bring in the laundry before it rains."}]},{"jlpt_level":"N4","sort_order":58,"additional_examples":[{"japanese":"今、昼ご飯を食べるところです。","romaji":"Ima, hirugohan o taberu tokoro desu.","meaning":"I am just about to eat lunch."},{"japanese":"母は料理を作っているところです。","romaji":"Haha wa ryouri o tsukutte iru tokoro desu.","meaning":"My mother is in the middle of cooking."},{"japanese":"今、駅に着いたところです。","romaji":"Ima, eki ni tsuita tokoro desu.","meaning":"I have just arrived at the station."},{"japanese":"これから会議を始めるところです。","romaji":"Kore kara kaigi o hajimeru tokoro desu.","meaning":"We are just about to start the meeting."}]},{"jlpt_level":"N4","sort_order":59,"additional_examples":[{"japanese":"日本に来たばかりなので、まだ道が分かりません。","romaji":"Nihon ni kita bakari na node, mada michi ga wakarimasen.","meaning":"I have only just come to Japan, so I still do not know the roads."},{"japanese":"新しい仕事を始めたばかりです。","romaji":"Atarashii shigoto o hajimeta bakari desu.","meaning":"I have just started a new job."},{"japanese":"昼ご飯を食べたばかりなので、おなかがいっぱいです。","romaji":"Hirugohan o tabeta bakari na node, onaka ga ippai desu.","meaning":"I have just eaten lunch, so I am full."},{"japanese":"この町に引っ越してきたばかりです。","romaji":"Kono machi ni hikkoshite kita bakari desu.","meaning":"I have only just moved to this town."}]},{"jlpt_level":"N4","sort_order":60,"additional_examples":[{"japanese":"最近、仕事が増えるばかりです。","romaji":"Saikin, shigoto ga fueru bakari desu.","meaning":"Recently, my workload just keeps increasing."},{"japanese":"この町の人口は減るばかりです。","romaji":"Kono machi no jinkou wa heru bakari desu.","meaning":"The population of this town keeps decreasing."},{"japanese":"物価は上がるばかりで、生活が大変です。","romaji":"Bukka wa agaru bakari de, seikatsu ga taihen desu.","meaning":"Prices keep rising, making life difficult."},{"japanese":"心配は大きくなるばかりです。","romaji":"Shinpai wa ookiku naru bakari desu.","meaning":"My worries just keep growing."}]},{"jlpt_level":"N4","sort_order":61,"additional_examples":[{"japanese":"夢のような景色を見ました。","romaji":"Yume no you na keshiki o mimashita.","meaning":"I saw a dreamlike view."},{"japanese":"彼女はモデルのような人です。","romaji":"Kanojo wa moderu no you na hito desu.","meaning":"She is a person like a model."},{"japanese":"子どものころに戻ったような気持ちです。","romaji":"Kodomo no koro ni modotta you na kimochi desu.","meaning":"It feels as if I have returned to my childhood."},{"japanese":"これは映画のような話ですね。","romaji":"Kore wa eiga no you na hanashi desu ne.","meaning":"This is like a story from a movie."}]},{"jlpt_level":"N4","sort_order":62,"additional_examples":[{"japanese":"子どもにも分かるように、簡単に説明しました。","romaji":"Kodomo ni mo wakaru you ni, kantan ni setsumei shimashita.","meaning":"I explained it simply so that even children could understand."},{"japanese":"忘れないように、カレンダーに書きました。","romaji":"Wasurenai you ni, karendaa ni kakimashita.","meaning":"I wrote it on the calendar so I would not forget."},{"japanese":"みんなに聞こえるように、大きな声で話してください。","romaji":"Minna ni kikoeru you ni, ookina koe de hanashite kudasai.","meaning":"Please speak loudly so everyone can hear."},{"japanese":"間違えないように、ゆっくり確認します。","romaji":"Machigaenai you ni, yukkuri kakunin shimasu.","meaning":"I will check slowly so I do not make a mistake."}]},{"jlpt_level":"N4","sort_order":63,"additional_examples":[{"japanese":"最近、日が長くなりました。","romaji":"Saikin, hi ga nagaku narimashita.","meaning":"Recently, the days have become longer."},{"japanese":"弟は医者になりました。","romaji":"Otouto wa isha ni narimashita.","meaning":"My younger brother became a doctor."},{"japanese":"部屋が静かになりました。","romaji":"Heya ga shizuka ni narimashita.","meaning":"The room became quiet."},{"japanese":"練習して、走るのが速くなりました。","romaji":"Renshuu shite, hashiru no ga hayaku narimashita.","meaning":"After practising, I became faster at running."}]},{"jlpt_level":"N4","sort_order":64,"additional_examples":[{"japanese":"飲み物はお茶にします。","romaji":"Nomimono wa ocha ni shimasu.","meaning":"I will have tea as my drink."},{"japanese":"昼ご飯はカレーにしました。","romaji":"Hirugohan wa karee ni shimashita.","meaning":"I chose curry for lunch."},{"japanese":"旅行の行き先は京都にします。","romaji":"Ryokou no ikisaki wa Kyoto ni shimasu.","meaning":"I will choose Kyoto as the travel destination."},{"japanese":"プレゼントはこの時計にします。","romaji":"Purezento wa kono tokei ni shimasu.","meaning":"I will choose this watch as the present."}]},{"jlpt_level":"N4","sort_order":65,"additional_examples":[{"japanese":"あの雲は犬みたいです。","romaji":"Ano kumo wa inu mitai desu.","meaning":"That cloud looks like a dog."},{"japanese":"彼は何でも知っているみたいです。","romaji":"Kare wa nandemo shitte iru mitai desu.","meaning":"It seems that he knows everything."},{"japanese":"この料理はカレーみたいな味がします。","romaji":"Kono ryouri wa karee mitai na aji ga shimasu.","meaning":"This dish tastes like curry."},{"japanese":"外は寒いみたいです。","romaji":"Soto wa samui mitai desu.","meaning":"It seems cold outside."}]},{"jlpt_level":"N4","sort_order":66,"additional_examples":[{"japanese":"田中さんは来月結婚するらしいです。","romaji":"Tanaka-san wa raigetsu kekkon suru rashii desu.","meaning":"Apparently, Tanaka is getting married next month."},{"japanese":"この店のケーキはおいしいらしいです。","romaji":"Kono mise no keeki wa oishii rashii desu.","meaning":"Apparently, the cakes at this shop are delicious."},{"japanese":"明日は電車が混むらしいです。","romaji":"Ashita wa densha ga komu rashii desu.","meaning":"Apparently, the trains will be crowded tomorrow."},{"japanese":"あの人は日本に十年住んでいたらしいです。","romaji":"Ano hito wa Nihon ni juu-nen sunde ita rashii desu.","meaning":"Apparently, that person lived in Japan for ten years."}]},{"jlpt_level":"N4","sort_order":67,"additional_examples":[{"japanese":"このケーキはおいしそうです。","romaji":"Kono keeki wa oishisou desu.","meaning":"This cake looks delicious."},{"japanese":"あの子は眠そうです。","romaji":"Ano ko wa nemusou desu.","meaning":"That child looks sleepy."},{"japanese":"雨が降りそうなので、傘を持って行きます。","romaji":"Ame ga furisou na node, kasa o motte ikimasu.","meaning":"It looks like it is going to rain, so I will take an umbrella."},{"japanese":"この荷物は重そうです。","romaji":"Kono nimotsu wa omosou desu.","meaning":"This luggage looks heavy."}]},{"jlpt_level":"N4","sort_order":68,"additional_examples":[{"japanese":"天気予報によると、明日は雪が降るそうです。","romaji":"Tenki yohou ni yoru to, ashita wa yuki ga furu sou desu.","meaning":"According to the weather forecast, it will snow tomorrow."},{"japanese":"田中さんは来月引っ越すそうです。","romaji":"Tanaka-san wa raigetsu hikkosu sou desu.","meaning":"I hear that Tanaka is moving next month."},{"japanese":"この店は来週から休みだそうです。","romaji":"Kono mise wa raishuu kara yasumi da sou desu.","meaning":"I hear that this shop will be closed starting next week."},{"japanese":"新しい駅ができるそうです。","romaji":"Atarashii eki ga dekiru sou desu.","meaning":"I hear that a new station will be built."}]},{"jlpt_level":"N4","sort_order":69,"additional_examples":[{"japanese":"明日は雪が降るかもしれません。","romaji":"Ashita wa yuki ga furu kamoshiremasen.","meaning":"It might snow tomorrow."},{"japanese":"彼はもう帰ったかもしれません。","romaji":"Kare wa mou kaetta kamoshiremasen.","meaning":"He may have already gone home."},{"japanese":"この店は日曜日に休みかもしれません。","romaji":"Kono mise wa nichiyoubi ni yasumi kamoshiremasen.","meaning":"This shop might be closed on Sunday."},{"japanese":"電車が少し遅れるかもしれません。","romaji":"Densha ga sukoshi okureru kamoshiremasen.","meaning":"The train might be a little late."}]},{"jlpt_level":"N4","sort_order":70,"additional_examples":[{"japanese":"今夜は雨が降るでしょう。","romaji":"Konya wa ame ga furu deshou.","meaning":"It will probably rain tonight."},{"japanese":"この道は夕方混むでしょう。","romaji":"Kono michi wa yuugata komu deshou.","meaning":"This road will probably be crowded in the evening."},{"japanese":"彼はもうすぐ到着するでしょう。","romaji":"Kare wa mou sugu touchaku suru deshou.","meaning":"He will probably arrive soon."},{"japanese":"来年はもっと暑くなるでしょう。","romaji":"Rainen wa motto atsuku naru deshou.","meaning":"Next year will probably become even hotter."}]},{"jlpt_level":"N4","sort_order":71,"additional_examples":[{"japanese":"彼はもう家に着いているはずです。","romaji":"Kare wa mou ie ni tsuite iru hazu desu.","meaning":"He should have arrived home by now."},{"japanese":"この電車は九時に駅に着くはずです。","romaji":"Kono densha wa ku-ji ni eki ni tsuku hazu desu.","meaning":"This train should arrive at the station at nine."},{"japanese":"鍵は机の上にあるはずです。","romaji":"Kagi wa tsukue no ue ni aru hazu desu.","meaning":"The key should be on the desk."},{"japanese":"田中さんは今日出勤するはずです。","romaji":"Tanaka-san wa kyou shukkin suru hazu desu.","meaning":"Tanaka is expected to come to work today."}]},{"jlpt_level":"N4","sort_order":72,"additional_examples":[{"japanese":"毎日練習しているので、上手なわけです。","romaji":"Mainichi renshuu shite iru node, jouzu na wake desu.","meaning":"No wonder he is good; he practises every day."},{"japanese":"電車が止まっていたので、遅れたわけです。","romaji":"Densha ga tomatte ita node, okureta wake desu.","meaning":"So that is why I was late: the train had stopped."},{"japanese":"彼は tenisu の選手です。強いわけですね。","romaji":"Kare wa tenisu no senshu desu. Tsuyoi wake desu ne.","meaning":"He is a tennis player. No wonder he is strong."},{"japanese":"毎晩勉強していたから、合格したわけです。","romaji":"Maiban benkyou shite ita kara, goukaku shita wake desu.","meaning":"That explains why she passed; she studied every night."}]},{"jlpt_level":"N4","sort_order":73,"additional_examples":[{"japanese":"高い物がいつもいいわけではありません。","romaji":"Takai mono ga itsumo ii wake dewa arimasen.","meaning":"Expensive things are not necessarily good."},{"japanese":"日本に住んでいる人が全員日本人というわけではありません。","romaji":"Nihon ni sunde iru hito ga zenin nihonjin to iu wake dewa arimasen.","meaning":"Not everyone who lives in Japan is Japanese."},{"japanese":"忙しいからといって、休めないわけではありません。","romaji":"Isogashii kara to itte, yasumenai wake dewa arimasen.","meaning":"Being busy does not mean you cannot take a break."},{"japanese":"一度失敗しても、夢をあきらめるわけではありません。","romaji":"Ichido shippai shite mo, yume o akirameru wake dewa arimasen.","meaning":"Even if I fail once, that does not mean I will give up on my dream."}]},{"jlpt_level":"N4","sort_order":74,"additional_examples":[{"japanese":"昨日は食べすぎました。","romaji":"Kinou wa tabesugimashita.","meaning":"I ate too much yesterday."},{"japanese":"このかばんは重すぎます。","romaji":"Kono kaban wa omosugimasu.","meaning":"This bag is too heavy."},{"japanese":"夜遅くまで働きすぎないでください。","romaji":"Yoru osoku made hatarakisuginaide kudasai.","meaning":"Please do not work too much until late at night."},{"japanese":"この説明は少し長すぎます。","romaji":"Kono setsumei wa sukoshi nagasugimasu.","meaning":"This explanation is a little too long."}]},{"jlpt_level":"N4","sort_order":75,"additional_examples":[{"japanese":"このペンは書きやすいです。","romaji":"Kono pen wa kakiyasui desu.","meaning":"This pen is easy to write with."},{"japanese":"このアプリは使いやすいです。","romaji":"Kono apuri wa tsukaiyasui desu.","meaning":"This app is easy to use."},{"japanese":"この靴は歩きやすいです。","romaji":"Kono kutsu wa arukiyasui desu.","meaning":"These shoes are comfortable to walk in."},{"japanese":"この本は言葉が簡単で読みやすいです。","romaji":"Kono hon wa kotoba ga kantan de yomiyasui desu.","meaning":"The words in this book are simple, so it is easy to read."}]},{"jlpt_level":"N4","sort_order":76,"additional_examples":[{"japanese":"この漢字は覚えにくいです。","romaji":"Kono kanji wa oboenikui desu.","meaning":"This kanji is difficult to remember."},{"japanese":"この道は狭くて歩きにくいです。","romaji":"Kono michi wa semakute arukinikui desu.","meaning":"This road is narrow and difficult to walk on."},{"japanese":"この説明は分かりにくいです。","romaji":"Kono setsumei wa wakarinikui desu.","meaning":"This explanation is difficult to understand."},{"japanese":"この靴は固くて走りにくいです。","romaji":"Kono kutsu wa katakute hashirinikui desu.","meaning":"These shoes are stiff and difficult to run in."}]},{"jlpt_level":"N4","sort_order":77,"additional_examples":[{"japanese":"子どもが急に泣き始めました。","romaji":"Kodomo ga kyuu ni nakihajimemashita.","meaning":"The child suddenly started crying."},{"japanese":"雨が降り始めました。","romaji":"Ame ga furihajimemashita.","meaning":"It started to rain."},{"japanese":"彼は日本語を勉強し始めました。","romaji":"Kare wa nihongo o benkyou shihajimemashita.","meaning":"He started studying Japanese."},{"japanese":"駅で電車が動き始めました。","romaji":"Eki de densha ga ugokihajimemashita.","meaning":"The train began moving at the station."}]},{"jlpt_level":"N4","sort_order":78,"additional_examples":[{"japanese":"レポートを書き終わりました。","romaji":"Repooto o kakiowarimashita.","meaning":"I finished writing the report."},{"japanese":"昼ご飯を食べ終わったら、出かけましょう。","romaji":"Hirugohan o tabeowattara, dekakemashou.","meaning":"Let's go out after we finish eating lunch."},{"japanese":"本を読み終わりました。","romaji":"Hon o yomiowarimashita.","meaning":"I finished reading the book."},{"japanese":"夕食を作り終わってから、電話します。","romaji":"Yuushoku o tsukuriowatte kara, denwa shimasu.","meaning":"I will call after I finish work."}]},{"jlpt_level":"N4","sort_order":79,"additional_examples":[{"japanese":"毎日運動を続けています。","romaji":"Mainichi undou o tsuzukete imasu.","meaning":"I continue exercising every day."},{"japanese":"彼女は三時間話し続けました。","romaji":"Kanojo wa san-jikan hanashitsuzukemashita.","meaning":"She continued talking for three hours."},{"japanese":"雨が一晩中降り続きました。","romaji":"Ame ga hitobanjuu furitsuzukimashita.","meaning":"The rain continued falling all night."},{"japanese":"日本語の勉強を続けたいです。","romaji":"Nihongo no benkyou o tsuzuketai desu.","meaning":"I want to continue studying Japanese."}]},{"jlpt_level":"N4","sort_order":80,"additional_examples":[{"japanese":"急に雨が降り出しました。","romaji":"Kyuu ni ame ga furidashimashita.","meaning":"It suddenly started raining."},{"japanese":"赤ちゃんが泣き出しました。","romaji":"Akachan ga nakidashimashita.","meaning":"The baby suddenly started crying."},{"japanese":"みんなが笑い出しました。","romaji":"Minna ga waraidashimashita.","meaning":"Everyone suddenly burst out laughing."},{"japanese":"風が急に吹き出しました。","romaji":"Kaze ga kyuu ni fukidashimashita.","meaning":"The wind suddenly began blowing strongly."}]},{"jlpt_level":"N4","sort_order":81,"additional_examples":[{"japanese":"明日までに返事をしてほしいです。","romaji":"Ashita made ni henji o shite hoshii desu.","meaning":"I want you to reply by tomorrow."},{"japanese":"もう少しゆっくり話してほしいです。","romaji":"Mou sukoshi yukkuri hanashite hoshii desu.","meaning":"I want you to speak a little more slowly."},{"japanese":"弟に部屋を片付けてほしいです。","romaji":"Otouto ni heya o katazukete hoshii desu.","meaning":"I want my younger brother to tidy his room."},{"japanese":"会議の時間を教えてほしいです。","romaji":"Kaigi no jikan o oshiete hoshii desu.","meaning":"I want you to tell me the meeting time."}]},{"jlpt_level":"N4","sort_order":82,"additional_examples":[{"japanese":"妹に数学を教えてあげました。","romaji":"Imouto ni suugaku o oshiete agemashita.","meaning":"I helped my younger sister by teaching her maths."},{"japanese":"友達の荷物を持ってあげました。","romaji":"Tomodachi no nimotsu o motte agemashita.","meaning":"I carried my friend's luggage for them."},{"japanese":"弟に新しい自転車を買ってあげました。","romaji":"Otouto ni atarashii jitensha o katte agemashita.","meaning":"I bought a new bicycle for my younger brother."},{"japanese":"困っている人に道を教えてあげました。","romaji":"Komatte iru hito ni michi o oshiete agemashita.","meaning":"I helped a person who was lost by showing them the way."}]},{"jlpt_level":"N4","sort_order":83,"additional_examples":[{"japanese":"友達が駅まで迎えに来てくれました。","romaji":"Tomodachi ga eki made mukae ni kite kuremashita.","meaning":"My friend came to pick me up at the station."},{"japanese":"母がお弁当を作ってくれました。","romaji":"Haha ga obentou o tsukutte kuremashita.","meaning":"My mother made a lunch box for me."},{"japanese":"隣の人がドアを開けてくれました。","romaji":"Tonari no hito ga doa o akete kuremashita.","meaning":"The person next to me opened the door for me."},{"japanese":"先生が作文を直してくれました。","romaji":"Sensei ga sakubun o naoshite kuremashita.","meaning":"The teacher corrected my essay for me."}]},{"jlpt_level":"N4","sort_order":84,"additional_examples":[{"japanese":"先生に作文を直してもらいました。","romaji":"Sensei ni sakubun o naoshite moraimashita.","meaning":"I had the teacher correct my essay for me."},{"japanese":"友達に駅まで送ってもらいました。","romaji":"Tomodachi ni eki made okutte moraimashita.","meaning":"A friend gave me a ride to the station."},{"japanese":"姉に日本語を教えてもらいました。","romaji":"Ane ni nihongo o oshiete moraimashita.","meaning":"I had my older sister teach me Japanese."},{"japanese":"店員にサイズを確認してもらいました。","romaji":"Tenin ni saizu o kakunin shite moraimashita.","meaning":"I had the shop assistant check the size for me."}]},{"jlpt_level":"N4","sort_order":85,"additional_examples":[{"japanese":"先生がゆっくり説明してくださいました。","romaji":"Sensei ga yukkuri setsumei shite kudasaimashita.","meaning":"The teacher kindly explained it slowly for me."},{"japanese":"部長が会議に参加してくださいました。","romaji":"Buchou ga kaigi ni sanka shite kudasaimashita.","meaning":"The department manager kindly took part in the meeting."},{"japanese":"先生が推薦状を書いてくださいました。","romaji":"Sensei ga suisenjou o kaite kudasaimashita.","meaning":"The teacher kindly wrote a recommendation letter for me."},{"japanese":"お客様が意見を聞かせてくださいました。","romaji":"Okyakusama ga iken o kikasete kudasaimashita.","meaning":"The customer kindly shared their opinion with us."}]},{"jlpt_level":"N4","sort_order":86,"additional_examples":[{"japanese":"先生に推薦状を書いていただきました。","romaji":"Sensei ni suisenjou o kaite itadakimashita.","meaning":"I gratefully received a recommendation letter written by my teacher."},{"japanese":"社長に直接お話ししていただきました。","romaji":"Shachou ni chokusetsu ohanashi shite itadakimashita.","meaning":"I was honoured to have the company president speak with me directly."},{"japanese":"先生に発音を教えていただきました。","romaji":"Sensei ni hatsuon o oshiete itadakimashita.","meaning":"I received pronunciation instruction from my teacher."},{"japanese":"専門家に説明していただきました。","romaji":"Senmonka ni setsumei shite itadakimashita.","meaning":"I had an expert explain it to me."}]},{"jlpt_level":"N4","sort_order":87,"additional_examples":[{"japanese":"妹に誕生日のプレゼントをあげました。","romaji":"Imouto ni tanjoubi no purezento o agemashita.","meaning":"I gave my younger sister a birthday present."},{"japanese":"友達に日本のお菓子をあげました。","romaji":"Tomodachi ni Nihon no okashi o agemashita.","meaning":"I gave my friend some Japanese sweets."},{"japanese":"子どもに絵本をあげました。","romaji":"Kodomo ni ehon o agemashita.","meaning":"I gave the child a picture book."},{"japanese":"母に花をあげました。","romaji":"Haha ni hana o agemashita.","meaning":"I gave my mother flowers."}]},{"jlpt_level":"N4","sort_order":88,"additional_examples":[{"japanese":"友達がコンサートのチケットをくれました。","romaji":"Tomodachi ga konsaato no chiketto o kuremashita.","meaning":"My friend gave me a concert ticket."},{"japanese":"姉が古いカメラをくれました。","romaji":"Ane ga furui kamera o kuremashita.","meaning":"My older sister gave me an old camera."},{"japanese":"先生が参考書をくださいました。","romaji":"Sensei ga sankousho o kudasaimashita.","meaning":"The teacher gave me a reference book."},{"japanese":"父が旅行のお土産をくれました。","romaji":"Chichi ga ryokou no omiyage o kuremashita.","meaning":"My father gave me a souvenir from his trip."}]},{"jlpt_level":"N4","sort_order":89,"additional_examples":[{"japanese":"先生から辞書をもらいました。","romaji":"Sensei kara jisho o moraimashita.","meaning":"I received a dictionary from my teacher."},{"japanese":"友達に誕生日カードをもらいました。","romaji":"Tomodachi ni tanjoubi kaado o moraimashita.","meaning":"I received a birthday card from my friend."},{"japanese":"姉から古い時計をもらいました。","romaji":"Ane kara furui tokei o moraimashita.","meaning":"I received an old watch from my older sister."},{"japanese":"会社から新しいパソコンをもらいました。","romaji":"Kaisha kara atarashii pasokon o moraimashita.","meaning":"I received a new computer from my company."}]},{"jlpt_level":"N4","sort_order":90,"additional_examples":[{"japanese":"私は日本語で自分の意見を話せます。","romaji":"Watashi wa nihongo de jibun no iken o hanasemasu.","meaning":"I can express my opinion in Japanese."},{"japanese":"この図書館では本を借りられます。","romaji":"Kono toshokan de wa hon o kariraremasu.","meaning":"You can borrow books at this library."},{"japanese":"妹は一人で自転車に乗れます。","romaji":"Imouto wa hitori de jitensha ni noremasu.","meaning":"My younger sister can ride a bicycle by herself."},{"japanese":"この映画はインターネットで見られます。","romaji":"Kono eiga wa intaanetto de miraremasu.","meaning":"You can see Mount Fuji from here."}]},{"jlpt_level":"N4","sort_order":91,"additional_examples":[{"japanese":"財布が電車の中で盗まれました。","romaji":"Saifu ga densha no naka de nusumaremashita.","meaning":"My wallet was stolen on the train."},{"japanese":"この建物は十年前に建てられました。","romaji":"Kono tatemono wa juu-nen mae ni tateraremashita.","meaning":"This building was built ten years ago."},{"japanese":"私の名前が新聞に載りました。","romaji":"Watashi no namae ga shinbun ni norimashita.","meaning":"My name appeared in the newspaper."},{"japanese":"この歌は多くの人に知られています。","romaji":"Kono uta wa ooku no hito ni shirarete imasu.","meaning":"This song is known by many people."}]},{"jlpt_level":"N4","sort_order":92,"additional_examples":[{"japanese":"母は子どもに野菜を食べさせました。","romaji":"Haha wa kodomo ni yasai o tabesasemashita.","meaning":"The mother made her child eat vegetables."},{"japanese":"先生は学生に教室を掃除させました。","romaji":"Sensei wa gakusei ni kyoushitsu o souji sasemashita.","meaning":"The teacher made the students clean the classroom."},{"japanese":"父は私を一人で旅行させてくれました。","romaji":"Chichi wa watashi o hitori de ryokou sasete kuremashita.","meaning":"My father let me travel alone."},{"japanese":"店長は店員に新しい商品を説明させました。","romaji":"Tenchou wa tenin ni atarashii shouhin o setsumei sasemashita.","meaning":"The manager made the staff explain the new product."}]},{"jlpt_level":"N4","sort_order":93,"additional_examples":[{"japanese":"財布には千円しかありません。","romaji":"Saifu ni wa sen-en shika arimasen.","meaning":"I have only one thousand yen in my wallet."},{"japanese":"今日は三十分しか勉強できませんでした。","romaji":"Kyou wa sanjuppun shika benkyou dekimasen deshita.","meaning":"I could study for only thirty minutes today."},{"japanese":"冷蔵庫に卵が一つしか残っていません。","romaji":"Reizouko ni tamago ga hitotsu shika nokotte imasen.","meaning":"There is only one egg left in the refrigerator."},{"japanese":"彼はひらがなしか読めません。","romaji":"Kare wa hiragana shika yomemasen.","meaning":"He can read only hiragana."}]},{"jlpt_level":"N4","sort_order":94,"additional_examples":[{"japanese":"このアプリを使うだけで、簡単に予約できます。","romaji":"Kono apuri o tsukau dake de, kantan ni yoyaku dekimasu.","meaning":"You can make a reservation easily just by using this app."},{"japanese":"名前を書くだけで、申し込みは終わります。","romaji":"Namae o kaku dake de, moushikomi wa owarimasu.","meaning":"The application is complete just by writing your name."},{"japanese":"ボタンを押すだけで、電気がつきます。","romaji":"Botan o osu dake de, denki ga tsukimasu.","meaning":"The light turns on just by pressing the button."},{"japanese":"この説明を読むだけで、使い方が分かります。","romaji":"Kono setsumei o yomu dake de, tsukaikata ga wakarimasu.","meaning":"You can understand how to use it just by reading this explanation."}]},{"jlpt_level":"N4","sort_order":95,"additional_examples":[{"japanese":"弟はゲームばかりしています。","romaji":"Otouto wa geemu bakari shite imasu.","meaning":"My younger brother does nothing but play games."},{"japanese":"最近、雨ばかり降っています。","romaji":"Saikin, ame bakari futte imasu.","meaning":"Recently, it has done nothing but rain."},{"japanese":"彼は文句ばかり言っています。","romaji":"Kare wa monku bakari itte imasu.","meaning":"He does nothing but complain."},{"japanese":"この店では甘い物ばかり買ってしまいます。","romaji":"Kono mise de wa amai mono bakari katte shimaimasu.","meaning":"I end up buying nothing but sweets at this shop."}]},{"jlpt_level":"N4","sort_order":96,"additional_examples":[{"japanese":"歩けないほど疲れました。","romaji":"Arukenai hodo tsukaremashita.","meaning":"I was so tired that I could not walk."},{"japanese":"声が出ないほど驚きました。","romaji":"Koe ga denai hodo odorokimashita.","meaning":"I was so surprised that I could not speak."},{"japanese":"涙が出るほど嬉しかったです。","romaji":"Namida ga deru hodo ureshikatta desu.","meaning":"I was so happy that tears came to my eyes."},{"japanese":"眠れないほど心配しました。","romaji":"Nemurenai hodo shinpai shimashita.","meaning":"I was so worried that I could not sleep."}]},{"jlpt_level":"N4","sort_order":97,"additional_examples":[{"japanese":"ここから駅まで歩いて五分くらいです。","romaji":"Koko kara eki made aruite go-fun kurai desu.","meaning":"It is about a five-minute walk from here to the station."},{"japanese":"毎日一時間くらい日本語を勉強します。","romaji":"Mainichi ichi-jikan kurai nihongo o benkyou shimasu.","meaning":"I study Japanese for about an hour every day."},{"japanese":"会議には二十人くらい来ました。","romaji":"Kaigi ni wa nijuu-nin kurai kimashita.","meaning":"About twenty people came to the meeting."},{"japanese":"この本は三百ページくらいあります。","romaji":"Kono hon wa sanbyaku peeji kurai arimasu.","meaning":"This book is about three hundred pages long."}]},{"jlpt_level":"N4","sort_order":98,"additional_examples":[{"japanese":"学生にプリントを二枚ずつ配りました。","romaji":"Gakusei ni purinto o ni-mai zutsu kubarimashita.","meaning":"I handed out two sheets to each student."},{"japanese":"子どもたちにりんごを一つずつあげました。","romaji":"Kodomotachi ni ringo o hitotsu zutsu agemashita.","meaning":"I gave each child one apple."},{"japanese":"毎日、単語を五つずつ覚えています。","romaji":"Mainichi, tango o itsutsu zutsu oboete imasu.","meaning":"I learn five words at a time every day."},{"japanese":"二人ずつグループを作ってください。","romaji":"Futari zutsu guruupu o tsukutte kudasai.","meaning":"Please make groups of two."}]},{"jlpt_level":"N4","sort_order":99,"additional_examples":[{"japanese":"ニュースによると、明日は雪だそうです。","romaji":"Nyuusu ni yoru to, ashita wa yuki da sou desu.","meaning":"According to the news, it will snow tomorrow."},{"japanese":"天気予報によると、週末は晴れるそうです。","romaji":"Tenki yohou ni yoru to, shuumatsu wa hareru sou desu.","meaning":"According to the weather forecast, it will be sunny this weekend."},{"japanese":"新聞によると、新しい駅ができるそうです。","romaji":"Shinbun ni yoru to, atarashii eki ga dekiru sou desu.","meaning":"According to the newspaper, a new station will be built."},{"japanese":"先生の話によると、試験は来週だそうです。","romaji":"Sensei no hanashi ni yoru to, shiken wa raishuu da sou desu.","meaning":"According to the teacher, the exam is next week."}]},{"jlpt_level":"N4","sort_order":100,"additional_examples":[{"japanese":"環境問題について、クラスで話し合いました。","romaji":"Kankyou mondai ni tsuite, kurasu de hanashiaimashita.","meaning":"We discussed environmental issues in class."},{"japanese":"日本の文化について調べています。","romaji":"Nihon no bunka ni tsuite shirabete imasu.","meaning":"I am researching Japanese culture."},{"japanese":"将来の仕事について、先生に相談しました。","romaji":"Shourai no shigoto ni tsuite, sensei ni soudan shimashita.","meaning":"I consulted my teacher about my future job."},{"japanese":"この本は日本の歴史について書いてあります。","romaji":"Kono hon wa Nihon no rekishi ni tsuite kaite arimasu.","meaning":"This book is written about Japanese history."}]}]$n4_examples$::jsonb;
  v_updated integer;
begin
  update public.grammar_points as grammar
  set examples = coalesce(grammar.examples, '[]'::jsonb) || item.additional_examples
  from jsonb_to_recordset(v_examples) as item(
    jlpt_level text,
    sort_order integer,
    additional_examples jsonb
  )
  where grammar.jlpt_level = item.jlpt_level
    and grammar.sort_order = item.sort_order;
  get diagnostics v_updated = row_count;
  if v_updated <> 100 then
    raise exception 'Expected to expand 100 N4 grammar sets, updated %', v_updated;
  end if;
end;
$expand_n4_grammar_examples$;
commit;
